p=argparse.ArgumentParser();p.add_argument('csv',type=Path);p.add_argument('output',type=Path);a=p.parse_args();rows=[{k:float(v) for k,v in x.items()} for x in csv.DictReader(a.csv.open())];assert len(rows)==96 and all(math.isfinite(v) for x in rows for v in x.values());on=[x for x in rows if x['gauge_variant']<2];full=[x for x in rows if x['gauge_variant']==3];theta=max(abs(x['Theta_transport_error']) for x in rows);z=max(x['Z_transport_error_max'] for x in rows);compatible=max(x['constraint_Sommerfeld_max'] for x in on);omitted=max(x['tangential_omission_max'] for x in rows);nontrivial=min(max(abs(x[k]) for x in full) for k in ['Theta','Z_conformal'])>1e-4;r=dict(passed=theta<=1e-8 and z<=1e-8 and compatible<=1e-8 and nontrivial,samples=len(rows),on_constraint_samples=len(on),full_off_constraint_samples=len(full),maximum_Theta_transport_error=theta,maximum_Z_transport_error=z,maximum_constraint_satisfying_Sommerfeld_residual=compatible,maximum_radial_only_tangential_omission=omitted,nontrivial_full_probes=nontrivial,maximum_connection_variation_error=max(max(x['connection_variation_error1'],x['connection_variation_error2']) for x in rows),scope='Exact finite-Omega coordinate-component constraint transport and outgoing-null residual. All native lower-order terms retained. Not a closed H/M/Theta/Z subsidiary wave analysis, absorbing SAT energy/reflection test, mapped seam proof or native evolution adoption.',csv_sha256=hashlib.sha256(a.csv.read_bytes()).hexdigest(),script_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest());a.output.write_text(json.dumps(r,indent=2)+'\n');print(r)
